/* Add shared snorkeling alternatives while preserving the original private tours. */
;(function addSharedSnorkelingPackages() {
  const packages = window.GREEN_TOURS_CONTENT.packages;
  const makeSharedPage = (sourceKey, price, message, title, description) => {
    const source = packages[sourceKey];
    const snorkeling = source.snorkeling;
    return {
      ...source,
      kicker: 'Shared snorkeling trip',
      title,
      description,
      price: 'Per person',
      size: 'Shared boat',
      message,
      rates: [['Per person', `IDR ${price.toLocaleString('en-US')}`]],
      rateUnit: 'per person',
      perPersonPrice: price,
      snorkeling: {
        ...snorkeling,
        includes: snorkeling.includes.map((item) => item === 'Private snorkeling boat' ? 'Shared snorkeling boat' : item),
        itinerary: snorkeling.itinerary.map(([time, heading, detail]) => [
          time,
          heading.replace(/Private Boat/gi, 'Shared Boat'),
          detail.replace(/private boat/gi, 'shared boat')
        ]),
        notes: snorkeling.notes.map((note) => note === 'This package includes a private boat exclusively for your group.'
          ? 'This package is on a shared boat with other guests.'
          : note)
      }
    };
  };
  packages.mantaShared = makeSharedPage(
    'manta', 395000, 'Shared Snorkeling Manta Point',
    'Shared snorkeling<br><i>Manta Point.</i>',
    'Join other guests aboard a shared snorkeling boat, swim in Manta Point’s blue waters, and experience one of Penida’s most memorable wildlife encounters.'
  );
  packages.matabayShared = makeSharedPage(
    'matabay', 295000, 'Shared Snorkeling Manta Bay',
    'Shared snorkeling<br><i>Manta Bay.</i>',
    'Join other guests aboard a shared snorkeling boat and explore Manta Bay’s clear, vibrant waters. Take time to snorkel, float, and savor the beauty around you.'
  );
  packages.matabayShared.time = '4 hours';
})();


